import React, { useState, useEffect } from 'react';
import { getAllEmployees } from '../../service/statisticsservice';
import './EmployeeList.scss';

const EmployeeList = () => {
    const [employees, setEmployees] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchData = async () => {
        try {
            const response = await getAllEmployees();
            setEmployees(response);
            // Gọi callback để cập nhật số lượng ở Homepage
            onEmployeeCountChange?.(response.length);
        } catch (error) {
            console.error("Error fetching employees:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const intervalId = setInterval(() => {
            fetchData();
        }, 5000);
        return () => clearInterval(intervalId);
    }, []);

    if (loading) {
        return (
            <div className="employee-list-section">
                <div className="card shadow-sm">
                    <div className="card-body text-center">
                        <div className="spinner-border text-primary" role="status">
                            <span className="visually-hidden">Đang tải...</span>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="employee-list-section">
            <div className="card shadow-sm">
                <div className="card-body">
                    <h5 className="card-title">Danh Sách Nhân Viên</h5>
                    <div className="table-responsive">
                        <table className="table table-bordered table-hover">
                            <thead className="table-dark">
                                <tr>
                                    <th>Mã NV</th>
                                    <th>Họ và tên</th>
                                    <th>Giới tính</th>
                                    <th>Phòng ban</th>
                                    <th>Loại hình</th>
                                    <th>Lương</th>
                                    <th>Ngày nghỉ</th>
                                    <th>Nguồn dữ liệu</th>
                                </tr>
                            </thead>
                            <tbody>
                                {employees.map((emp) => (
                                    <tr key={emp.employee_id}>
                                        <td>{emp.employee_id}</td>
                                        <td>{`${emp.first_name} ${emp.last_name}`}</td>
                                        <td>{emp.gender ? 'Nam' : 'Nữ'}</td>
                                        <td>{emp.department || 'N/A'}</td>
                                        <td>{emp.employment_type === 'Full-time' ? 'Toàn thời gian' : 'Bán thời gian'}</td>
                                        <td className="text-end">{emp.pay_amount ? new Intl.NumberFormat('vi-VN', {
                                            style: 'currency',
                                            currency: 'VND'
                                        }).format(emp.pay_amount) : 'N/A'}</td>
                                        <td className="text-end">{emp.vacation_days || 'N/A'}</td>
                                        <td>{emp.data_source}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default EmployeeList;
